// The installer against what the release pipeline itself produces: a D1 worker entry generated by
// scripts/release/manifest-lib.ts, and a statement signed by scripts/release/release-signing.ts.
import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { SigningIdentity } from "@schoolos/fleet";
import { pinReleaseKeys } from "@schoolos/releases";
import { describe, expect, it } from "vitest";
import { collectModules } from "../../../scripts/release/hash-lib.ts";
import { buildWorkerEntry, readD1Migrations } from "../../../scripts/release/manifest-lib.ts";
import { signReleaseManifest } from "../../../scripts/release/release-signing.ts";
import { compileDesiredState, install, loadPinnedManifest, type WorkerEntry } from "../src/index.ts";
import { accountFor, configFor, deriveRelease, goldenRelease, NORTHFIELD, SECRETS, tokenFor } from "./support.ts";

const BUNDLES = fileURLToPath(new URL("../../../scripts/release/testdata/fixture-bundles/", import.meta.url));

/** gatekeeper-google as manifest-lib would emit it had it declared a D1 database with migrations. */
function googleWithD1(migrations: Record<string, string>) {
  const dir = mkdtempSync(join(tmpdir(), "schoolos-installer-d1-"));
  mkdirSync(join(dir, "migrations"));
  for (const [file, sql] of Object.entries(migrations)) writeFileSync(join(dir, "migrations", file), sql);
  const config = {
    name: "gatekeeper-google",
    main: "src/index.ts",
    compatibility_date: "2026-01-01",
    d1_databases: [{ binding: "GOOGLE_DB", database_name: "local", database_id: "local-id" }],
  };
  const d1Migrations = readD1Migrations({ name: "gatekeeper-google", dir, config });
  const { mainModule, modules } = collectModules(join(BUNDLES, "gatekeeper-google"));
  return { entry: buildWorkerEntry({ pkgName: "gatekeeper-google", config, mainModule, modules, d1Migrations }), d1Migrations };
}

describe("release pipeline output", () => {
  it("installs a D1 database and runs the migrations manifest-lib emits", async () => {
    const golden = await goldenRelease();
    const { entry, d1Migrations } = googleWithD1({
      "0001_tokens.sql": "CREATE TABLE tokens (id TEXT PRIMARY KEY);",
      "0002_grants.sql": "CREATE TABLE grants (id TEXT PRIMARY KEY);",
    });
    // Strict parsing in deriveRelease is the compatibility check: an unknown field fails it.
    const release = await deriveRelease(golden, "r000001-fixture", async (m, artifacts) => {
      m.workers["gatekeeper-google"] = entry as WorkerEntry;
      for (const migration of d1Migrations) await artifacts.addBlob(new Uint8Array(migration.bytes));
    });
    const config = configFor(NORTHFIELD, release);

    const database = compileDesiredState(release.manifest, config).resources.find((r) => r.kind === "d1_database");
    expect(database).toMatchObject({ name: "schoolos-northfield-google-db", migrations: [{ id: "0001_tokens" }, { id: "0002_grants" }] });

    const fake = accountFor(NORTHFIELD);
    const { tokens } = tokenFor(fake, "district-run");
    await install({ api: fake.api(tokens), config, manifest: release.manifest, artifacts: release.artifacts, secrets: SECRETS });
    expect(fake.d1Statements("schoolos-northfield-google-db")).toEqual([
      "CREATE TABLE tokens (id TEXT PRIMARY KEY);",
      "CREATE TABLE grants (id TEXT PRIMARY KEY);",
    ]);
  });

  it("accepts a manifest signed by the release pipeline under a signed pin", async () => {
    const golden = await goldenRelease();
    const key = await SigningIdentity.generate();
    const signedManifest = await signReleaseManifest(golden.bytes, key, { version: "0.3.0", channel: "stable" });
    const trust = await pinReleaseKeys([key.publicKey]);
    const pin = { mode: "signed", releaseId: golden.manifest.releaseId, version: "0.3.0", trust } as const;

    const manifest = await loadPinnedManifest(golden.bytes, pin, { signedManifest });
    expect(manifest.releaseId).toBe(golden.manifest.releaseId);
    await expect(loadPinnedManifest(golden.bytes, { ...pin, version: "0.4.0" }, { signedManifest }))
      .rejects.toMatchObject({ code: "validation-failed" });
  });
});
